 @Test void orderConsumesQuoteAndFreezesFactsAtomically(){String u=consumer(),o=ready();shipping();String quote=q(u,o,List.of());var result=order(u,quote,key());assertEquals(200,result.status(),result.body().toString());assertEquals(2500,result.data().get("payable_amount_fen").asInt());assertEquals(2,reserved(o));assertEquals(20,balance(o));assertEquals("PENDING",result.data().get("payment").get("status").asString());assertEquals(0,read("/consumer/cart",u).data().get("items").size());assertEquals("CONSUMED",read("/consumer/checkout/quotes/"+quote,u).data().get("status").asString());assertEquals(1,db.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregate_id=? AND event_type='OrderCreated'",Integer.class,result.id()));assertEquals(200,patch(o,Map.of("sale_price_fen",2000),1).status());assertEquals(result.data().get("pricing_snapshot"),read("/consumer/orders/"+result.id(),u).data().get("pricing_snapshot"));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE orders SET payable_amount_fen=payable_amount_fen+1 WHERE id=?",UUID.fromString(result.id())));}
 @Test void keyReplayAndQuoteSingleConsumption(){String u=consumer(),o=ready();shipping();String quote=q(u,o,List.of()),k=key();var first=order(u,quote,k);assertEquals(200,first.status(),first.body().toString());assertEquals(first.data(),order(u,quote,k).data());assertEquals("QUOTE_ALREADY_CONSUMED",order(u,quote,key()).body().get("error").get("code").asString());assertEquals(409,order(u,UUID.randomUUID().toString(),k).status());assertEquals(2,reserved(o));assertEquals(1,db.queryForObject("SELECT count(*) FROM orders WHERE user_id=?",Integer.class,user(u)));}
 @Test void realmsOwnershipAndNoAmountOverride(){String u=consumer(),o=ready();shipping();String quote=q(u,o,List.of());assertEquals(401,order(null,quote,key()).status());assertEquals(403,order(merchant,quote,key()).status());assertEquals(404,order(consumer(),quote,key()).status());assertEquals(400,req("POST","/consumer/orders",Map.of("quote_id",quote,"payable_amount_fen",1),u,Map.of("Idempotency-Key",key())).status());var first=order(u,quote,key());assertEquals(200,first.status(),first.body().toString());assertEquals(404,read("/consumer/orders/"+first.id(),consumer()).status());assertEquals(403,read("/admin/orders/"+first.id(),reader).status());assertEquals(200,read("/admin/orders/"+first.id(),admin).status());assertEquals(200,read("/consumer/orders",u).status());assertEquals(200,read("/admin/orders",admin).status());assertEquals(200,read("/merchant/suborders",merchant).status());String sub=first.data().get("suborders").get(0).get("id").asString();assertEquals(200,read("/merchant/suborders/"+sub,merchant).status());assertEquals(403,read("/merchant/suborders/"+sub,colleague).status());assertEquals(403,read("/merchant/suborders/"+sub,foreign).status());}
 @Test void cancellationReleasesOnceAndPreservesAmounts(){String u=consumer(),o=ready();shipping();String c=coupon(u,"PLATFORM",200,0),quote=q(u,o,List.of(c));var first=order(u,quote,key());assertEquals(200,first.status(),first.body().toString());assertEquals("RESERVED",db.queryForObject("SELECT status FROM user_coupons WHERE id=?",String.class,UUID.fromString(c)));String id=first.id(),k=key();assertEquals(428,req("POST","/consumer/orders/"+id+"/cancel",Map.of("reason_code","CONSUMER_CANCELLED"),u,Map.of("Idempotency-Key",key())).status());assertEquals(409,cancel(u,id,9,key()).status());assertEquals(404,cancel(consumer(),id,0,key()).status());var result=cancel(u,id,0,k);assertEquals(200,result.status(),result.body().toString());assertEquals(result.data(),cancel(u,id,0,k).data());assertEquals("CANCELLED",result.data().get("status").asString());assertEquals("CLOSED",result.data().get("payment").get("status").asString());assertEquals(2300,result.data().get("payable_amount_fen").asInt());assertEquals(0,reserved(o));assertEquals(20,balance(o));assertEquals("AVAILABLE",db.queryForObject("SELECT status FROM user_coupons WHERE id=?",String.class,UUID.fromString(c)));assertEquals(1,db.queryForObject("SELECT count(*) FROM order_cancellations WHERE order_id=?",Integer.class,UUID.fromString(id)));assertEquals(2,db.queryForObject("SELECT cancelled_qty FROM order_items WHERE suborder_id=?",Integer.class,UUID.fromString(result.data().get("suborders").get(0).get("id").asString())));assertEquals(409,cancel(u,id,1,key()).status());assertEquals(400,req("POST","/consumer/orders/"+id+"/cancel",Map.of("reason_code","CONSUMER_CANCELLED","items",List.of()),u,Map.of("Idempotency-Key",key(),"If-Match","\"1\"")).status());}
 @Test void returnedCouponRestoresOriginAndExpiredCouponExpires(){String u=consumer(),o=ready();shipping();String c=coupon(u,"PLATFORM",200,0);db.update("UPDATE user_coupons SET status='RETURNED',version=version+1 WHERE id=?",UUID.fromString(c));var first=order(u,q(u,o,List.of(c)),key());assertEquals(200,first.status(),first.body().toString());assertEquals(200,cancel(u,first.id(),0,key()).status());assertEquals("RETURNED",db.queryForObject("SELECT status FROM user_coupons WHERE id=?",String.class,UUID.fromString(c)));var next=order(u,q(u,o,List.of(c)),key());assertEquals(200,next.status(),next.body().toString());db.update("UPDATE auth_session SET expires_at=refresh_expires_at WHERE access_token_hash=?",crypto.hash(u));OFFSET.set(1000);assertTrue(orders.expireBatch()>=1);assertEquals(0,orders.expireBatch());var expired=read("/consumer/orders/"+next.id(),u);assertEquals(200,expired.status());assertEquals("PAYMENT_WINDOW_EXPIRED",expired.data().get("cancellation").get("reason_code").asString());assertEquals("EXPIRED",expired.data().get("reservations").get(0).get("status").asString());assertEquals("EXPIRED",db.queryForObject("SELECT status FROM user_coupons WHERE id=?",String.class,UUID.fromString(c)));assertEquals(0,reserved(o));}
