 @Test void concurrentLastStockNeverOversells()throws Exception{String u=consumer(),v=consumer(),o=ready();shipping();assertEquals(201,adjust(o,-18,1,key(),merchant).status());String q1=q(u,o,List.of()),q2=q(v,o,List.of());var pool=Executors.newFixedThreadPool(2);try{var start=new CountDownLatch(1);var a=pool.submit(()->{start.await();return order(u,q1,key());});var b=pool.submit(()->{start.await();return order(v,q2,key());});start.countDown();var x=a.get(20,TimeUnit.SECONDS);var y=b.get(20,TimeUnit.SECONDS);assertEquals(Set.of(200,409),Set.of(x.status(),y.status()),x.body()+" / "+y.body());assertEquals(2,reserved(o));assertEquals(1,db.queryForObject("SELECT count(*) FROM orders WHERE user_id IN (?,?)",Integer.class,user(u),user(v)));}finally{pool.shutdownNow();}}
