 @Test void outboxFailureRollsBackEveryBusinessFact(){String u=consumer(),o=ready();shipping();String c=coupon(u,"PLATFORM",200,0),quote=q(u,o,List.of(c));db.execute("CREATE FUNCTION fail_order_outbox() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.event_type='OrderCreated' THEN RAISE EXCEPTION 'TEST rollback'; END IF; RETURN NEW; END $$");db.execute("CREATE TRIGGER test_fail_order_outbox BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_order_outbox()");try{assertEquals(503,order(u,quote,key()).status());assertEquals(0,reserved(o));assertEquals("AVAILABLE",db.queryForObject("SELECT status FROM user_coupons WHERE id=?",String.class,UUID.fromString(c)));assertEquals("ACTIVE",db.queryForObject("SELECT status FROM pricing_quotes WHERE id=?",String.class,UUID.fromString(quote)));assertEquals(0,db.queryForObject("SELECT count(*) FROM orders WHERE user_id=?",Integer.class,user(u)));assertEquals(1,read("/consumer/cart",u).data().get("items").size());}finally{db.execute("DROP TRIGGER test_fail_order_outbox ON outbox_event");db.execute("DROP FUNCTION fail_order_outbox()");}assertEquals(200,order(u,quote,key()).status());}
 @Test void orderPolicyRequiresProofAndDoesNotChangeOldExpiry(){String u=consumer(),o=ready();shipping();var first=order(u,q(u,o,List.of()),key());assertEquals(200,first.status());String expiry=first.data().get("reservation_expires_at").asString();var body=Map.of("version_code","TEST_"+key().replace("-","").toUpperCase(),"reservation_ttl_seconds",60);assertEquals(200,read("/admin/order-policies",admin).status());assertEquals(403,req("POST","/admin/order-policies",body,admin,Map.of("Idempotency-Key",key())).status());String p=crypto.token();db.update("INSERT INTO reverify_grant(token_hash,session_id,action,expires_at,created_at) VALUES (?,?,'order.policy.manage',?,?)",crypto.hash(p),adminSession,Timestamp.from(clock.instant().plusSeconds(120)),Timestamp.from(clock.instant()));String k=key();var policy=req("POST","/admin/order-policies",body,admin,Map.of("Idempotency-Key",k,"X-Reverify-Token",p));assertEquals(200,policy.status(),policy.body().toString());assertEquals(policy.data(),req("POST","/admin/order-policies",body,admin,Map.of("Idempotency-Key",k,"X-Reverify-Token",p)).data());assertEquals(expiry,read("/consumer/orders/"+first.id(),u).data().get("reservation_expires_at").asString());var second=order(u,q(u,o,List.of()),key());assertEquals(200,second.status());assertTrue(Instant.parse(second.data().get("reservation_expires_at").asString()).isBefore(Instant.parse(expiry)));}

 @Test void crossMerchantOrderHasTwoGroupsAndAtomicFailure(){String u=consumer(),o=ready();shipping();var b=createBody(null);b.put("store_id",db.queryForObject("SELECT ss.store_id FROM principal_store_scope ss JOIN auth_session s ON s.principal_id=ss.principal_id WHERE s.access_token_hash=?",UUID.class,crypto.hash(foreign)).toString());String f=req("POST","/merchant/offers",b,foreign,Map.of("Idempotency-Key",key())).id();assertEquals(201,adjust(f,20,0,key(),foreign).status());assertEquals(200,state(f,"activate",0,foreign,null,key()).status());UUID fm=db.queryForObject("SELECT merchant_id FROM offers WHERE id=?",UUID.class,UUID.fromString(f));db.update("INSERT INTO shipping_rule_versions(id,merchant_id,version_no,province_codes,base_fen,per_kg_fen,created_by) VALUES (?,?,1,'[\"310000\"]',300,100,?)",UUID.randomUUID(),fm,adminPrincipal);String i=addFor(u,o),j=addFor(u,f),addr=addressFor(u);var input=Map.of("cart_item_ids",List.of(i,j),"address_id",addr);var q1=req("POST","/consumer/checkout/quotes",input,u,Map.of("Idempotency-Key",key()));assertEquals(200,q1.status(),q1.body().toString());assertEquals(201,adjust(f,-19,1,key(),foreign).status());var failed=order(u,q1.data().get("quote_id").asString(),key());assertEquals(409,failed.status());assertEquals(0,reserved(o));assertEquals(0,reserved(f));assertEquals(0,db.queryForObject("SELECT count(*) FROM orders WHERE user_id=?",Integer.class,user(u)));assertEquals(201,adjust(f,19,2,key(),foreign).status());var q2=req("POST","/consumer/checkout/quotes",input,u,Map.of("Idempotency-Key",key()));assertEquals(200,q2.status());var created=order(u,q2.data().get("quote_id").asString(),key());assertEquals(200,created.status(),created.body().toString());assertEquals(2,created.data().get("suborders").size());assertEquals(5000,created.data().get("payable_amount_fen").asInt());assertEquals(2,reserved(o));assertEquals(2,reserved(f));assertEquals(200,cancel(u,created.id(),0,key()).status());assertEquals(0,reserved(o));assertEquals(0,reserved(f));}
 @Test void sharedOfferAcrossPetsAggregatesReservationAndRejectsOversell(){String u=consumer(),o=ready();shipping();assertEquals(201,adjust(o,-17,1,key(),merchant).status());String i=addFor(u,o);var other=req("POST","/consumer/cart/items",Map.of("offer_id",o,"quantity",2,"pet_id",pet(u,"CAT").toString()),u,Map.of("Idempotency-Key",key()));assertEquals(200,other.status());String a=addressFor(u);var q=req("POST","/consumer/checkout/quotes",Map.of("cart_item_ids",List.of(i,other.id()),"address_id",a),u,Map.of("Idempotency-Key",key()));assertEquals(200,q.status(),q.body().toString());assertEquals(409,order(u,q.data().get("quote_id").asString(),key()).status());assertEquals(0,reserved(o));assertEquals(0,db.queryForObject("SELECT count(*) FROM orders WHERE user_id=?",Integer.class,user(u)));assertEquals(201,adjust(o,1,2,key(),merchant).status());var q2=req("POST","/consumer/checkout/quotes",Map.of("cart_item_ids",List.of(i,other.id()),"address_id",a),u,Map.of("Idempotency-Key",key()));var created=order(u,q2.data().get("quote_id").asString(),key());assertEquals(200,created.status(),created.body().toString());assertEquals(1,created.data().get("reservations").size());assertEquals(4,reserved(o));assertEquals(2,created.data().get("suborders").get(0).get("items").size());}
 @Test void storeScopedEmployeeCannotReadMixedScopeChildOrForeignMerchant(){String u=consumer(),o=ready();shipping();String defaultOffer=req("POST","/merchant/offers",createBody(null),merchant,Map.of("Idempotency-Key",key())).id();assertEquals(201,adjust(defaultOffer,20,0,key(),merchant).status());assertEquals(200,state(defaultOffer,"activate",0,merchant,null,key()).status());String i=addFor(u,o),j=addFor(u,defaultOffer),a=addressFor(u);var q=req("POST","/consumer/checkout/quotes",Map.of("cart_item_ids",List.of(i,j),"address_id",a),u,Map.of("Idempotency-Key",key()));var created=order(u,q.data().get("quote_id").asString(),key());assertEquals(200,created.status());String sub=created.data().get("suborders").get(0).get("id").asString();String scoped=identity("MERCHANT",merchantId,List.of("order.read"));assertEquals(404,read("/merchant/suborders/"+sub,scoped).status());assertEquals(0,read("/merchant/suborders",scoped).data().size());assertEquals(200,read("/merchant/suborders/"+sub,merchant).status());UUID fm=db.queryForObject("SELECT p.merchant_id FROM identity_principal p JOIN auth_session s ON s.principal_id=p.id WHERE s.access_token_hash=?",UUID.class,crypto.hash(foreign));UUID originalStore=store;store=db.queryForObject("SELECT id FROM merchant_store WHERE merchant_id=? LIMIT 1",UUID.class,fm);String outsider=identity("MERCHANT",fm,List.of("order.read","order.default-scope"));store=originalStore;assertEquals(404,read("/merchant/suborders/"+sub,outsider).status());}
 @Test void parallelExpiryWorkersReleaseEachOrderOnce()throws Exception{String u=consumer(),o=ready();shipping();var one=order(u,q(u,o,List.of()),key());var two=order(u,q(u,o,List.of()),key());assertEquals(200,one.status());assertEquals(200,two.status());OFFSET.set(1000);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->orders.expireBatch());var b=pool.submit(()->orders.expireBatch());a.get(20,TimeUnit.SECONDS);b.get(20,TimeUnit.SECONDS);assertEquals(0,reserved(o));assertEquals(2,db.queryForObject("SELECT count(*) FROM order_cancellations WHERE order_id IN (?,?)",Integer.class,UUID.fromString(one.id()),UUID.fromString(two.id())));assertEquals(2,db.queryForObject("SELECT count(*) FROM inventory_reservation_events WHERE order_id IN (?,?) AND operation='EXPIRE'",Integer.class,UUID.fromString(one.id()),UUID.fromString(two.id())));assertEquals(0,orders.expireBatch());}finally{pool.shutdownNow();}}
 @Test void reservationBlocksMerchantDamageAndPaginationIsExplicit(){String u=consumer(),o=ready();shipping();var first=order(u,q(u,o,List.of()),key());assertEquals(200,first.status());assertEquals(409,adjust(o,-19,2,key(),merchant).status());assertEquals(20,balance(o));var second=order(u,q(u,o,List.of()),key());assertEquals(200,second.status());var page=read("/consumer/orders?limit=1",u);assertEquals(200,page.status());assertTrue(page.body().get("page").get("has_more").asBoolean());String cursor=page.body().get("page").get("next_cursor").asString();var next=read("/consumer/orders?limit=1&cursor="+cursor,u);assertEquals(1,next.data().size());assertNotEquals(page.data().get(0).get("id").asString(),next.data().get(0).get("id").asString());assertFalse(next.body().get("page").get("has_more").asBoolean());}
